################################################################################
# ANALYTIC TAYLOR REPRESENTATION OF FOURIER-BESSEL BASES
#
# For a Fourier-Bessel radial function y(k) = J_j(kr) of integer order j, the
# normalized Taylor coefficients about k₀,
#
#                  y(k₀ + δ) = Σₙ₌₀ᵖ aₙ δⁿ,
#
# are generated by the same Bessel-equation recurrence used for the
# corner-adapted basis (see `_besselj_taylor_coefficients!` in
# corneradapted_recurrence.jl). Only J_j(k₀r) and J_{j+1}(k₀r) are evaluated
# directly; values and wavenumber derivatives at nearby k follow from Horner
# evaluation.
#
# The cache stores the radial coordinates, Taylor coefficients and the angular
# factors T(jφ) ∈ {cos(jφ), sin(jφ)}. When `gradients = true`, sin(φ), cos(φ)
# and the angular derivative ∂_φ T(jφ) are stored as well.
################################################################################

"""
    FourierBesselTaylorCache{T<:Real} <: BasisCache

Cache for the analytic Taylor representation of a [`FourierBessel`](@ref)
basis about a reference wavenumber.

## Description
For each spatial point and basis function, the cache stores the normalized
Taylor coefficients of the radial factor `J_j(kr)` about `k0` together with
the angular factor `T(jφ)` (`cos` or `sin`, as selected by `basis.trig`).

The coefficient tensor is indexed as `coeffs[l + 1, p, c]`, where `l` is the
Taylor order, `p` the spatial point and `c` the basis-function index.

The geometric quantities required for Cartesian spatial gradients are optional
and are constructed only when the cache is created from a basis with
`gradients = true`.

## Attributes
* `k0`: Reference wavenumber of the Taylor expansion.
* `degree`: Degree of the Taylor expansion.
* `r`: Radial coordinates of the evaluation points.
* `coeffs`: Normalized Taylor coefficients of `J_j(kr)`.
* `ang`: Angular factors `T(jφ)` for every point and basis function.
* `sinφ`: Values of `sin(φ + rot_angle)`, the sine of the global polar angle, when spatial-gradient data are requested, otherwise `nothing`.
* `cosφ`: Values of `cos(φ + rot_angle)`, the cosine of the global polar angle, when spatial-gradient data are requested, otherwise `nothing`.
* `dang`: Angular derivatives `∂_φ T(jφ)` when spatial-gradient data are requested, otherwise `nothing`.
"""
struct FourierBesselTaylorCache{T<:Real} <: BasisCache
    k0::T
    degree::Int
    r::Vector{T}
    coeffs::Array{T,3}
    ang::Matrix{T}
    sinφ::Union{Nothing,Vector{T}}
    cosφ::Union{Nothing,Vector{T}}
    dang::Union{Nothing,Matrix{T}}
end

"""
    FourierBesselTaylorCache(basis::FourierBessel{T}, k0::T, pts::AbstractArray; multithreaded::Bool = true) where {T<:Real} → cache::FourierBesselTaylorCache{T}

Construct an analytic Taylor representation of a [`FourierBessel`](@ref) basis
about the reference wavenumber `k0`.

## Description
The Taylor degree is taken from `basis.taylor_degree`. For each spatial point
and basis function, the normalized Taylor coefficients of `J_j(kr)` are
constructed analytically from Bessel's differential equation. The angular
factors required for basis evaluation are always cached. If
`basis.gradients` is `true`, `sin(φ)`, `cos(φ)` and `∂_φ T(jφ)` are also
stored.

## Arguments
* `basis`: [`FourierBessel`](@ref) basis to expand.
* `k0`: Reference wavenumber of the Taylor expansion.
* `pts`: Spatial points at which the basis will be evaluated.

## Keyword Arguments
* `multithreaded::Bool = true`: Enable multithreaded cache construction across basis functions.

## Returns
* `cache`: [`FourierBesselTaylorCache`](@ref) containing the analytic Taylor representation of the basis.
"""
function FourierBesselTaylorCache(basis::FourierBessel{T}, k0::T, pts::AbstractArray; multithreaded::Bool = true) where {T<:Real}
    deg = basis.taylor_degree
    M = length(pts)
    N = basis.dim
    r, φ = _fb_polar_coords(basis, pts)
    coeffs = Array{T,3}(undef, deg + 1, M, N)
    ang = Matrix{T}(undef, M, N)
    sinφ = basis.gradients ? Vector{T}(undef, M) : nothing
    cosφ = basis.gradients ? Vector{T}(undef, M) : nothing
    dang = basis.gradients ? Matrix{T}(undef, M, N) : nothing
    if basis.gradients
        @inbounds @simd for p = 1:M
            sinφ[p], cosφ[p] = sincos(φ[p] + basis.rot_angle)
        end
    end
    @use_threads multithreading=multithreaded for c = 1:N
        m = T(basis.orders[c])
        cosine = basis.trig[c] > 0
        @inbounds for p = 1:M
            s, co = sincos(m * φ[p])
            ang[p, c] = cosine ? co : s
            if basis.gradients
                dang[p, c] = cosine ? -m * s : m * co
            end
            _besselj_taylor_coefficients!(coeffs, p, c, m, k0, r[p], deg)
        end
    end
    return FourierBesselTaylorCache(k0, deg, r, coeffs, ang, sinφ, cosφ, dang)
end

"""
    basis_cache(basis::FourierBessel, k0, pts; multithreaded::Bool = true) → cache::FourierBesselTaylorCache

Construct the Taylor cache associated with a [`FourierBessel`](@ref) basis.

## Arguments
* `basis`: Basis for which the cache is constructed.
* `k0`: Reference wavenumber of the Taylor expansion.
* `pts`: Points at which the basis is represented.

## Keyword Arguments
* `multithreaded::Bool = true`: Whether cache construction is multithreaded.

## Returns
* `cache`: [`FourierBesselTaylorCache`](@ref) associated with `basis`.
"""
@inline function basis_cache(basis::FourierBessel, k0, pts; multithreaded::Bool = true)
    return FourierBesselTaylorCache(basis, k0, pts; multithreaded)
end

"""
    basis_matrix(cache::FourierBesselTaylorCache{T}, k::T; multithreaded::Bool = true) where {T<:Real} → B::Matrix{T}

Evaluate a cached Fourier-Bessel basis matrix at wavenumber `k`.

## Description
The radial Taylor series stored in `cache` is evaluated at `δ = k - cache.k0`
using Horner's rule and multiplied by the cached angular factor.

## Arguments
* `cache`: [`FourierBesselTaylorCache`](@ref) containing the Taylor coefficients and angular factors.
* `k`: Wavenumber at which the basis is evaluated.

## Keyword Arguments
* `multithreaded::Bool = true`: Enable multithreaded evaluation across basis functions.

## Returns
* `B`: Basis matrix of size `(M, N)`.
"""
function basis_matrix(cache::FourierBesselTaylorCache{T}, k::T; multithreaded::Bool = true) where {T<:Real}
    M = size(cache.coeffs, 2)
    N = size(cache.coeffs, 3)
    δ = k - cache.k0
    B = Matrix{T}(undef, M, N)
    @use_threads multithreading=multithreaded for c = 1:N
        @inbounds @simd for p = 1:M
            B[p, c] = _horner(cache.coeffs, p, c, δ) * cache.ang[p, c]
        end
    end
    return filter_matrix!(B)
end

"""
    dk_matrix(cache::FourierBesselTaylorCache{T}, k::T; multithreaded::Bool = true) where {T<:Real} → dB_dk::Matrix{T}

Evaluate the wavenumber derivative of a cached Fourier-Bessel basis matrix at
wavenumber `k`.

## Description
The radial Taylor series stored in `cache` is differentiated and evaluated at
`δ = k - cache.k0` using simultaneous Horner evaluation, then multiplied by the
cached angular factor.

## Arguments
* `cache`: [`FourierBesselTaylorCache`](@ref) containing the Taylor coefficients and angular factors.
* `k`: Wavenumber at which the derivative is evaluated.

## Keyword Arguments
* `multithreaded::Bool = true`: Enable multithreaded evaluation across basis functions.

## Returns
* `dB_dk`: Wavenumber derivative of the basis matrix, of size `(M, N)`.
"""
function dk_matrix(cache::FourierBesselTaylorCache{T}, k::T; multithreaded::Bool = true) where {T<:Real}
    M = size(cache.coeffs, 2)
    N = size(cache.coeffs, 3)
    δ = k - cache.k0
    dB_dk = Matrix{T}(undef, M, N)
    @use_threads multithreading=multithreaded for c = 1:N
        @inbounds @simd for p = 1:M
            _, dy = _horner_with_derivative(cache.coeffs, p, c, δ)
            dB_dk[p, c] = dy * cache.ang[p, c]
        end
    end
    return filter_matrix!(dB_dk)
end

"""
    _weight_scaled_basis_and_dk_matrices(cache::FourierBesselTaylorCache{T}, k::T, w::AbstractVector, nsym; multithreaded::Bool = true) where {T<:Real} → (B, dB_dk)::Tuple{Matrix{T},Matrix{T}}

Evaluate a cached Fourier-Bessel basis matrix and its wavenumber derivative
simultaneously at wavenumber `k`, with rows scaled by `sqrt(nsym * w)`.

## Arguments
* `cache`: [`FourierBesselTaylorCache`](@ref) containing the Taylor coefficients and angular factors.
* `k`: Wavenumber at which the basis and its derivative are evaluated.
* `w`: Vector of quadrature weights associated with the cached points.
* `nsym`: = one(eltype(w)) * (isnothing(basis.symmetries) ? 1 : length(basis.symmetries) + 1)

## Keyword Arguments
* `multithreaded::Bool = true`: Enable multithreaded evaluation across basis functions.

## Returns
* `(B, dB_dk)`: Weight-scaled basis matrix and its wavenumber derivative, each of size `(M, N)`.
"""
function _weight_scaled_basis_and_dk_matrices(cache::FourierBesselTaylorCache{T}, k::T, w::AbstractVector, nsym; multithreaded::Bool = true) where {T<:Real}
    M = size(cache.coeffs, 2)
    N = size(cache.coeffs, 3)
    length(w) == M || throw(DimensionMismatch("number of weights must equal number of cached points"))
    δ = k - cache.k0
    fw = Vector{T}(undef, M)
    α = sqrt(T(nsym))
    @inbounds @simd for p = 1:M
        fw[p] = α * sqrt(T(w[p]))
    end
    B = Matrix{T}(undef, M, N)
    dB_dk = Matrix{T}(undef, M, N)
    @use_threads multithreading=multithreaded for c = 1:N
        @inbounds @simd for p = 1:M
            y, dy = _horner_with_derivative(cache.coeffs, p, c, δ)
            f = fw[p] * cache.ang[p, c]
            B[p, c] = y * f
            dB_dk[p, c] = dy * f
        end
    end
    return filter_matrix!(B), filter_matrix!(dB_dk)
end

@inline function _require_gradient_cache(cache::FourierBesselTaylorCache)
    cache.sinφ === nothing && throw(ArgumentError("spatial-gradient data are not available; construct the cache from a basis with gradients = true"))
    return nothing
end

"""
    gradient_matrices(cache::FourierBesselTaylorCache{T}, basis::FourierBessel{T}, k::T; multithreaded::Bool = true) where {T<:Real} → (dB_dx, dB_dy)::Tuple{Matrix{T},Matrix{T}}

Evaluate the Cartesian spatial derivatives of a cached Fourier-Bessel basis at
wavenumber `k`.

## Description
For `r > 0`, the radial spatial derivative satisfies
\$\\partial_r J_j(kr) = (k/r)\\partial_k J_j(kr)\$, so the Taylor series and its
derivative yield both the radial and angular parts of the gradient without
additional Bessel-function evaluations. Points at the origin are assigned a
zero gradient. The cache must have been constructed with `gradients = true`.

## Arguments
* `cache`: [`FourierBesselTaylorCache`](@ref) containing the Taylor coefficients and spatial-gradient data.
* `basis`: [`FourierBessel`](@ref) basis associated with the cache.
* `k`: Wavenumber at which the spatial gradients are evaluated.

## Keyword Arguments
* `multithreaded::Bool = true`: Enable multithreaded evaluation across basis functions.

## Returns
* `(dB_dx, dB_dy)`: Cartesian `x` and `y` derivatives of the basis matrix, each of size `(M, N)`.
"""
function gradient_matrices(cache::FourierBesselTaylorCache{T}, basis::FourierBessel{T}, k::T; multithreaded::Bool = true) where {T<:Real}
    _require_gradient_cache(cache)
    M = size(cache.coeffs, 2)
    N = size(cache.coeffs, 3)
    N == basis.dim || throw(DimensionMismatch("cache and basis dimensions do not agree"))
    δ = k - cache.k0
    dB_dx = Matrix{T}(undef, M, N)
    dB_dy = Matrix{T}(undef, M, N)
    sinφ = cache.sinφ::Vector{T}
    cosφ = cache.cosφ::Vector{T}
    dang = cache.dang::Matrix{T}
    @use_threads multithreading=multithreaded for c = 1:N
        @inbounds for p = 1:M
            r = cache.r[p]
            if r == zero(T)
                dB_dx[p, c] = zero(T)
                dB_dy[p, c] = zero(T)
            else
                y, dy = _horner_with_derivative(cache.coeffs, p, c, δ)
                invr = inv(r)
                fr = k * dy * invr * cache.ang[p, c]
                fφ = y * dang[p, c]
                dB_dx[p, c] = cosφ[p] * fr - sinφ[p] * invr * fφ
                dB_dy[p, c] = sinφ[p] * fr + cosφ[p] * invr * fφ
            end
        end
    end
    return filter_matrix!(dB_dx), filter_matrix!(dB_dy)
end

"""
    basis_and_gradient_matrices(cache::FourierBesselTaylorCache{T}, basis::FourierBessel{T}, k::T; multithreaded::Bool = true) where {T<:Real} → (B, dB_dx, dB_dy)::Tuple{Matrix{T},Matrix{T},Matrix{T}}

Evaluate a cached Fourier-Bessel basis matrix and its Cartesian spatial
derivatives simultaneously at wavenumber `k`.

## Description
The radial Taylor series and its first wavenumber derivative are evaluated
simultaneously using Horner's rule, and the cached angular factors are used to
construct the basis matrix and its Cartesian derivatives as in
[`gradient_matrices`](@ref). The cache must have been constructed with
`gradients = true`.

## Arguments
* `cache`: [`FourierBesselTaylorCache`](@ref) containing the Taylor coefficients and spatial-gradient data.
* `basis`: [`FourierBessel`](@ref) basis associated with the cache.
* `k`: Wavenumber at which the basis and spatial gradients are evaluated.

## Keyword Arguments
* `multithreaded::Bool = true`: Enable multithreaded evaluation across basis functions.

## Returns
* `(B, dB_dx, dB_dy)`: Basis matrix and its Cartesian `x` and `y` derivatives, each of size `(M, N)`.
"""
function basis_and_gradient_matrices(cache::FourierBesselTaylorCache{T}, basis::FourierBessel{T}, k::T; multithreaded::Bool = true) where {T<:Real}
    _require_gradient_cache(cache)
    M = size(cache.coeffs, 2)
    N = size(cache.coeffs, 3)
    N == basis.dim || throw(DimensionMismatch("cache and basis dimensions do not agree"))
    δ = k - cache.k0
    B = Matrix{T}(undef, M, N)
    dB_dx = Matrix{T}(undef, M, N)
    dB_dy = Matrix{T}(undef, M, N)
    sinφ = cache.sinφ::Vector{T}
    cosφ = cache.cosφ::Vector{T}
    dang = cache.dang::Matrix{T}
    @use_threads multithreading=multithreaded for c = 1:N
        @inbounds for p = 1:M
            r = cache.r[p]
            y, dy = _horner_with_derivative(cache.coeffs, p, c, δ)
            a = cache.ang[p, c]
            B[p, c] = y * a
            if r == zero(T)
                dB_dx[p, c] = zero(T)
                dB_dy[p, c] = zero(T)
            else
                invr = inv(r)
                fr = k * dy * invr * a
                fφ = y * dang[p, c]
                dB_dx[p, c] = cosφ[p] * fr - sinφ[p] * invr * fφ
                dB_dy[p, c] = sinφ[p] * fr + cosφ[p] * invr * fφ
            end
        end
    end
    return filter_matrix!(B), filter_matrix!(dB_dx), filter_matrix!(dB_dy)
end
